        print(f"\nout-of-scope hosts seen (NOT tested): {', '.join(oos[:15])}")
    else:                                      # offline regex self-test
        rel, ab = set(), set()
        _mine('a "/api/completion" b fetch("/api/v1/users") <a href="https://api.acme.com/x">'
              ' "/graphql" "https://www.googleapis.com/y"', rel, ab)
